const ctx = $input.first().json;
const clamp = (n, min, max) => Math.max(min, Math.min(max, Number.isFinite(n) ? n : 0));
const threshold = (value, table, unknown = 0) => {
  if (value === null || value === undefined || Number.isNaN(Number(value))) return { points: unknown, reason: 'Input is unknown', threshold: null, value };
  for (const row of table) if (Number(value) >= row.min) return { points: row.points, reason: row.reason, threshold: row.min, value };
  return { points: 0, reason: 'Below scoring threshold', threshold: null, value };
};
const penaltyMap = {
  hard_exclusion: { points: -30, reason: 'ICP hard exclusion applies' },
  high_republication: { points: -12, reason: 'Signal may be inflated by republications' },
  low_confidence_identity: { points: -10, reason: 'Company identity is uncertain' },
  stale_source: { points: -8, reason: 'Source data is stale' },
  health_risk: { points: -8, reason: 'Legal or financial risk requires caution' },
  missing_core_inputs: { points: -6, reason: 'Core scoring inputs are incomplete' }
};
const tables = {
  volume: [{ min: 20, points: 25, reason: 'Very high active offer volume over 30 days' }, { min: 10, points: 18, reason: 'High active offer volume over 30 days' }, { min: 5, points: 12, reason: 'Moderate active offer volume over 30 days' }, { min: 1, points: 5, reason: 'At least one active offer over 30 days' }],
  acceleration: [{ min: 3, points: 20, reason: 'Recruitment pace is sharply accelerating' }, { min: 2, points: 15, reason: 'Recruitment pace is accelerating' }, { min: 1.2, points: 8, reason: 'Recruitment pace is slightly above baseline' }],
  tension: [{ min: 0.6, points: 15, reason: 'Majority of offers are in tension families' }, { min: 0.35, points: 10, reason: 'Significant share of offers are in tension families' }, { min: 0.15, points: 5, reason: 'Some tension-family hiring detected' }],
  diversity_training: [{ min: 0.45, points: 10, reason: 'Diverse job families create cross-training opportunity' }, { min: 0.25, points: 6, reason: 'Several job families detected' }, { min: 0.01, points: 3, reason: 'Focused hiring still has a training angle' }],
  multisite: [{ min: 5, points: 10, reason: 'Hiring spans many proven establishments' }, { min: 2, points: 7, reason: 'Hiring spans multiple proven establishments' }, { min: 1, points: 2, reason: 'Single proven establishment' }],
  icp: [{ min: 55, points: 10, reason: 'Company matches the V1 ICP' }, { min: 30, points: 6, reason: 'Company is partly aligned with the ICP' }, { min: 10, points: 2, reason: 'Company is only weakly aligned with the ICP' }],
  freshness_quality: [{ min: 0.85, points: 10, reason: 'Fresh and high-quality source data' }, { min: 0.65, points: 7, reason: 'Usable source freshness and quality' }, { min: 0.4, points: 3, reason: 'Stale or incomplete but still usable source data' }]
};
const scoreOne = (c) => {
  const breakdown = [
    ['volume', c.active_offer_count_30d], ['acceleration', c.acceleration_index], ['tension', c.tension_share_30d], ['diversity_training', c.diversity_index], ['multisite', c.multisite_index], ['icp', c.icp_score], ['freshness_quality', c.freshness_quality]
  ].map(([key, value]) => ({ key, ...threshold(value, tables[key]) }));
  const business = breakdown.reduce((sum, row) => sum + row.points, 0);
  const penalties = (c.penalty_keys || []).map((key) => ({ key, ...(penaltyMap[key] || { points: 0, reason: 'Unknown penalty ignored' }) }));
  const risk = Math.max(-30, penalties.reduce((sum, p) => sum + p.points, 0));
  const score = clamp(business + risk, 0, 100);
  const priority_label = score >= 70 ? 'Chaud' : score >= 45 ? 'À qualifier' : score >= 25 ? 'Veille' : 'Écarté';
  const reasons = [...breakdown.filter((r) => r.points > 0).sort((a, b) => b.points - a.points).slice(0, 5).map((r) => r.reason), ...penalties.map((p) => p.reason)].slice(0, 7);
  const keyMode = ctx.mode === 'simulate' ? `simulation:${ctx.score_as_of}` : 'current';
  return { score_key: `${c.company_key || 'unknown'}:${ctx.rule_version}:${keyMode}`, company_key: c.company_key || 'unknown', score_version: ctx.rule_version, inputs_version: 'g8n.inputs.scoring.v1', business_points: business, risk_penalty_points: risk, priority_label, score, confidence: c.confidence ?? 0.5, freshness: c.freshness_quality ?? 0, reasons_json: JSON.stringify(reasons), breakdown_json: JSON.stringify(breakdown), penalties_json: JSON.stringify(penalties), score_as_of: ctx.score_as_of, scored_at: new Date().toISOString(), is_current: ctx.mode === 'simulate' ? 'false' : 'true' };
};
if (ctx.status !== 'active' && ctx.mode !== 'simulate') throw new Error('Inactive scoring rule cannot write current scores');
return (ctx.companies || []).map((json) => ({ json: scoreOne(json) }));
